<script setup lang="ts">
import { ref, watch } from 'vue'
import TravelModal from './TravelModal.vue'
import type { Place } from '../stores/places'
import type { TripRecord, TripStopInput, TripStopRecord } from '../api/trips'
const props=defineProps<{trip:TripRecord;places:Place[];stop?:TripStopRecord|null;date:string;busy:boolean;initialPlace?:string;apiError?:string}>()
const emit=defineEmits<{close:[];save:[input:TripStopInput]}>()
const placeId=ref(props.stop?.placeId||props.initialPlace||''),name=ref(props.stop?.placeName||''),category=ref(props.stop?.category||'活动'),day=ref(props.stop?.dayDate||props.date||props.trip.startsOn||''),time=ref(props.stop?.startsAt||'09:00'),duration=ref(props.stop?.durationMinutes||60),cost=ref(Number(props.stop?.estimatedCost||0)),note=ref(props.stop?.note||''),completed=ref(!!props.stop?.completed)
watch(placeId,id=>{const place=props.places.find(item=>item.id===id);if(place){name.value=place.name;category.value=place.category}},{immediate:!props.stop})
function save(){emit('save',{placeId:placeId.value||null,placeName:name.value.trim(),category:category.value,dayDate:day.value,startsAt:time.value,durationMinutes:duration.value,note:note.value,sortOrder:props.stop?.sortOrder??props.trip.stops.length,estimatedCost:cost.value,completed:completed.value})}
</script>
<template><TravelModal :title="stop?'编辑这项安排':'添加一项安排'" eyebrow="PLAN THE DAY" :locked="busy" :error="apiError" @close="emit('close')"><form @submit.prevent="save"><div class="tw-modal-body"><div class="tw-field"><label for="ts-place">从收藏地点选择</label><select id="ts-place" v-model="placeId"><option value="">自行填写活动或交通安排</option><option v-for="place in places" :key="place.id" :value="place.id">{{ place.name }} · {{ place.city }}</option></select></div><div class="tw-field"><label for="ts-title">安排名称</label><input id="ts-title" v-model="name" maxlength="180" required placeholder="例如：逛博物馆、午餐或前往机场"/></div><div class="tw-form-grid"><div class="tw-field"><label for="ts-kind">类型</label><select id="ts-kind" v-model="category"><option v-for="item in ['景点','美食','咖啡','住宿','交通','活动']" :key="item">{{ item }}</option></select></div><div class="tw-field"><label for="ts-day">日期</label><input id="ts-day" v-model="day" type="date" required :min="trip.startsOn||undefined" :max="trip.endsOn||undefined"/></div></div><div class="tw-form-grid"><div class="tw-field"><label for="ts-time">开始时间</label><input id="ts-time" v-model="time" type="time" required/></div><div class="tw-field"><label for="ts-duration">停留时长（分钟）</label><input id="ts-duration" v-model.number="duration" type="number" min="1" max="1440" required/></div></div><div class="tw-field"><label for="ts-cost">计划费用（人民币）</label><input id="ts-cost" v-model.number="cost" type="number" min="0" max="999999999" step="0.01" required/><small>这是你的计划估算，实际支出请在旅行账本记录。</small></div><div class="tw-field"><label for="ts-note">备注与预约信息</label><textarea id="ts-note" v-model="note" maxlength="500" rows="3" placeholder="预约时间、交通提示，或其他提醒"></textarea></div><label class="tw-check"><input v-model="completed" type="checkbox"/>已经完成这项安排</label></div><footer class="tw-modal-footer"><button type="button" class="tw-button secondary" :disabled="busy" @click="emit('close')">取消</button><button class="tw-button primary" :disabled="busy">{{ busy?'保存中…':'保存安排' }}</button></footer></form></TravelModal></template>
